use anyhow::Result;
use codeflow_core::events::EventBuffer;
use codeflow_core::proto;
use flate2::write::GzEncoder;
use flate2::Compression;
use prost::Message;
use std::io::Write;
use std::time::{Duration, Instant};

use crate::paths;

const BATCH_MAX_EVENTS: usize = 50;
const BATCH_MAX_BYTES: usize = 512 * 1024;
const BATCH_FLUSH_INTERVAL: Duration = Duration::from_secs(30);
const MAX_RETRIES: u32 = 8;
const CIRCUIT_BREAKER_THRESHOLD: u32 = 5;
const CIRCUIT_BREAKER_COOLDOWN: Duration = Duration::from_secs(600);

pub struct SyncConfig {
    pub api_url: String,
    pub api_key: Option<String>,
    pub one_shot: bool,
}

impl Default for SyncConfig {
    fn default() -> Self {
        Self {
            api_url: std::env::var("CODEFLOW_API_URL")
                .unwrap_or_else(|_| "http://localhost:8080".to_string()),
            api_key: std::env::var("CODEFLOW_API_KEY").ok(),
            one_shot: false,
        }
    }
}

pub fn run(config: SyncConfig) -> Result<()> {
    let db_path = paths::db_path();
    if !db_path.exists() {
        println!("No events to sync.");
        return Ok(());
    }

    let event_buf = EventBuffer::open(&db_path)?;
    let pending = event_buf.pending_count()?;
    println!("Pending events: {}", pending);

    if pending == 0 {
        println!("Nothing to sync.");
        return Ok(());
    }

    let mut circuit_failures: u32 = 0;
    let mut circuit_open_until: Option<Instant> = None;

    loop {
        if let Some(open_until) = circuit_open_until {
            if Instant::now() < open_until {
                if config.one_shot {
                    eprintln!("Circuit breaker open. Retry later.");
                    return Ok(());
                }
                let remaining = open_until - Instant::now();
                tracing::warn!(secs = remaining.as_secs(), "circuit breaker open, waiting");
                std::thread::sleep(remaining.min(Duration::from_secs(10)));
                continue;
            }
            circuit_open_until = None;
            circuit_failures = 0;
        }

        let batch = event_buf.consume_batch(BATCH_MAX_EVENTS)?;
        if batch.is_empty() {
            if config.one_shot {
                println!("All events synced.");
                return Ok(());
            }
            std::thread::sleep(BATCH_FLUSH_INTERVAL);
            continue;
        }

        let ids: Vec<i64> = batch.iter().map(|(id, _)| *id).collect();
        let events: Vec<proto::Event> = batch.into_iter().map(|(_, e)| e).collect();

        let payload = encode_batch(&events, &config)?;

        if payload.len() > BATCH_MAX_BYTES {
            tracing::warn!(
                size = payload.len(),
                "batch exceeds max bytes, splitting not implemented — sending anyway"
            );
        }

        match send_batch(&config, &payload) {
            Ok(()) => {
                event_buf.mark_consumed(&ids)?;
                event_buf.purge_consumed()?;
                circuit_failures = 0;
                tracing::info!(count = ids.len(), "batch synced");
                println!("  Synced {} events", ids.len());
            }
            Err(e) => {
                circuit_failures += 1;
                tracing::error!(err = %e, failures = circuit_failures, "sync failed");
                eprintln!("  Sync failed: {} (attempt {}/{})", e, circuit_failures, CIRCUIT_BREAKER_THRESHOLD);

                if circuit_failures >= CIRCUIT_BREAKER_THRESHOLD {
                    circuit_open_until = Some(Instant::now() + CIRCUIT_BREAKER_COOLDOWN);
                    tracing::warn!("circuit breaker opened");
                    eprintln!("  Circuit breaker opened — will retry in {}s", CIRCUIT_BREAKER_COOLDOWN.as_secs());
                }

                if config.one_shot {
                    return Err(e);
                }

                let backoff = Duration::from_secs(2u64.pow(circuit_failures.min(MAX_RETRIES)));
                std::thread::sleep(backoff);
            }
        }
    }
}

fn encode_batch(events: &[proto::Event], config: &SyncConfig) -> Result<Vec<u8>> {
    let batch = proto::EventBatch {
        cli_version: env!("CARGO_PKG_VERSION").to_string(),
        machine_id: machine_id(),
        events: events.to_vec(),
    };

    let mut proto_buf = Vec::with_capacity(batch.encoded_len());
    batch.encode(&mut proto_buf)?;

    let mut encoder = GzEncoder::new(Vec::new(), Compression::fast());
    encoder.write_all(&proto_buf)?;
    let compressed = encoder.finish()?;

    tracing::debug!(
        proto_size = proto_buf.len(),
        gzip_size = compressed.len(),
        ratio = format!("{:.1}%", (1.0 - compressed.len() as f64 / proto_buf.len() as f64) * 100.0),
        "batch encoded"
    );

    let _ = config; // config used for future auth headers
    Ok(compressed)
}

fn send_batch(config: &SyncConfig, payload: &[u8]) -> Result<()> {
    let url = format!("{}/v1/events", config.api_url);

    let mut req = ureq::post(&url)
        .header("Content-Type", "application/x-protobuf")
        .header("Content-Encoding", "gzip");

    if let Some(key) = &config.api_key {
        req = req.header("Authorization", &format!("Bearer {}", key));
    }

    let mut resp = req.send(payload)
        .map_err(|e| anyhow::anyhow!("ingest API request failed: {}", e))?;

    let status = resp.status().as_u16();
    if status >= 400 {
        let body = resp.body_mut().read_to_string()
            .unwrap_or_default();
        anyhow::bail!("ingest API returned {}: {}", status, body);
    }

    Ok(())
}

fn machine_id() -> String {
    std::env::var("CODEFLOW_MACHINE_ID").unwrap_or_else(|_| {
        let hostname = hostname::get()
            .map(|h| h.to_string_lossy().to_string())
            .unwrap_or_else(|_| "unknown".to_string());
        let hash = blake3::hash(hostname.as_bytes());
        hash.to_hex()[..16].to_string()
    })
}

package main

import (
	"context"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/codeflow-dev/codeflow/cloud/internal/api"
	"github.com/codeflow-dev/codeflow/cloud/internal/clickhouse"
)

func main() {
	logger := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo}))
	slog.SetDefault(logger)

	chDSN := envOr("CLICKHOUSE_DSN", "clickhouse://localhost:9000/codeflow")
	listenAddr := envOr("LISTEN_ADDR", ":8080")

	ch, err := clickhouse.New(chDSN)
	if err != nil {
		slog.Error("failed to connect to clickhouse", "error", err)
		os.Exit(1)
	}
	defer ch.Close()

	slog.Info("connected to clickhouse", "dsn", chDSN)

	handler := api.NewRouter(ch, logger)

	srv := &http.Server{
		Addr:         listenAddr,
		Handler:      handler,
		ReadTimeout:  30 * time.Second,
		WriteTimeout: 30 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	go func() {
		slog.Info("ingest API listening", "addr", listenAddr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			slog.Error("server error", "error", err)
			os.Exit(1)
		}
	}()

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	slog.Info("shutting down...")
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(ctx); err != nil {
		slog.Error("shutdown error", "error", err)
	}
	slog.Info("server stopped")
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

package api

import (
	"compress/gzip"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"time"

	"github.com/codeflow-dev/codeflow/cloud/internal/clickhouse"
	"google.golang.org/protobuf/proto"

	pb "github.com/codeflow-dev/codeflow/cloud/proto"
)

type handler struct {
	ch     *clickhouse.Client
	logger *slog.Logger
}

func (h *handler) handleIngestEvents(w http.ResponseWriter, r *http.Request) {
	tenantID := extractTenantID(r)
	if tenantID == "" {
		tenantID = "default"
	}

	var reader io.Reader = r.Body
	if r.Header.Get("Content-Encoding") == "gzip" {
		gz, err := gzip.NewReader(r.Body)
		if err != nil {
			http.Error(w, "invalid gzip", http.StatusBadRequest)
			return
		}
		defer gz.Close()
		reader = gz
	}

	body, err := io.ReadAll(io.LimitReader(reader, 10*1024*1024))
	if err != nil {
		http.Error(w, "read error", http.StatusBadRequest)
		return
	}

	var batch pb.EventBatch
	if err := proto.Unmarshal(body, &batch); err != nil {
		http.Error(w, fmt.Sprintf("invalid protobuf: %v", err), http.StatusBadRequest)
		return
	}

	rows := make([]clickhouse.EventRow, 0, len(batch.Events))
	for _, ev := range batch.Events {
		row := clickhouse.EventRow{
			EventID:    ev.Id,
			TenantID:   tenantID,
			Timestamp:  time.UnixMilli(ev.TimestampMs),
			SessionID:  ev.SessionId,
			ProjectDir: ev.ProjectDir,
			Command:    ev.Command,
			CLIVersion: batch.CliVersion,
			MachineID:  batch.MachineId,
		}

		if ev.Compression != nil {
			row.EventType = "compression"
			row.InputBytes = ev.Compression.InputBytes
			row.OutputBytes = ev.Compression.OutputBytes
			row.InputTokens = ev.Compression.InputTokens
			row.OutputTokens = ev.Compression.OutputTokens
			row.TokensSaved = ev.Compression.TokensSaved
			row.FilterName = ev.Compression.FilterName
			row.CompressionLevel = ev.Compression.CompressionLevel
			row.LatencyMs = ev.Compression.LatencyMs
		}

		if ev.Dedup != nil {
			row.EventType = "dedup"
			row.ContentHash = ev.Dedup.ContentHash
			row.CacheHit = ev.Dedup.CacheHit
			row.TokensSaved = ev.Dedup.TokensSaved
			row.LatencyMs = ev.Dedup.LatencyMs
		}

		rows = append(rows, row)
	}

	if err := h.ch.InsertEvents(r.Context(), rows); err != nil {
		h.logger.Error("clickhouse insert failed", "error", err, "count", len(rows))
		http.Error(w, "insert failed", http.StatusInternalServerError)
		return
	}

	h.logger.Info("events ingested",
		"tenant", tenantID,
		"count", len(rows),
		"cli_version", batch.CliVersion,
	)

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusAccepted)
	json.NewEncoder(w).Encode(map[string]any{
		"accepted": len(rows),
	})
}

func (h *handler) handleOverview(w http.ResponseWriter, r *http.Request) {
	tenantID := r.URL.Query().Get("tenant_id")
	if tenantID == "" {
		tenantID = extractTenantID(r)
	}
	if tenantID == "" {
		tenantID = "default"
	}

	stats, err := h.ch.GetOverview(r.Context(), tenantID)
	if err != nil {
		h.logger.Error("overview query failed", "error", err)
		http.Error(w, "query failed", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(stats)
}

func extractTenantID(r *http.Request) string {
	if auth := r.Header.Get("Authorization"); auth != "" {
		// Future: extract tenant_id from JWT claims
		// For MVP: use X-Tenant-ID header (server-trusted in prod via gateway)
	}
	return r.Header.Get("X-Tenant-ID")
}

package api

import (
	"log/slog"
	"net/http"

	"github.com/codeflow-dev/codeflow/cloud/internal/clickhouse"
)

func NewRouter(ch *clickhouse.Client, logger *slog.Logger) http.Handler {
	mux := http.NewServeMux()

	h := &handler{ch: ch, logger: logger}

	mux.HandleFunc("POST /v1/events", h.handleIngestEvents)
	mux.HandleFunc("GET /v1/overview", h.handleOverview)
	mux.HandleFunc("GET /healthz", handleHealthz)

	return withLogging(logger, mux)
}

func handleHealthz(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(`{"status":"ok"}`))
}

func withLogging(logger *slog.Logger, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		logger.Info("request",
			"method", r.Method,
			"path", r.URL.Path,
			"remote", r.RemoteAddr,
		)
		next.ServeHTTP(w, r)
	})
}

package clickhouse

import (
	"context"
	"fmt"
	"time"

	ch "github.com/ClickHouse/clickhouse-go/v2"
)

type Client struct {
	conn ch.Conn
}

type EventRow struct {
	EventID          string
	TenantID         string
	Timestamp        time.Time
	SessionID        string
	ProjectDir       string
	Command          string
	EventType        string
	InputBytes       uint64
	OutputBytes      uint64
	InputTokens      uint64
	OutputTokens     uint64
	TokensSaved      uint64
	FilterName       string
	CompressionLevel string
	LatencyMs        float64
	ContentHash      string
	CacheHit         bool
	CLIVersion       string
	MachineID        string
}

type OverviewStats struct {
	TotalInputTokens  uint64  `json:"total_input_tokens"`
	TotalOutputTokens uint64  `json:"total_output_tokens"`
	TotalSaved        uint64  `json:"total_saved"`
	SavingsPct        float64 `json:"savings_pct"`
	EventCount        uint64  `json:"event_count"`
	TopCommands       []CommandStat `json:"top_commands"`
}

type CommandStat struct {
	Command string `json:"command"`
	Saved   uint64 `json:"saved"`
	Count   uint64 `json:"count"`
}

func New(dsn string) (*Client, error) {
	opts, err := ch.ParseDSN(dsn)
	if err != nil {
		return nil, fmt.Errorf("parse dsn: %w", err)
	}

	conn, err := ch.Open(opts)
	if err != nil {
		return nil, fmt.Errorf("open connection: %w", err)
	}

	if err := conn.Ping(context.Background()); err != nil {
		return nil, fmt.Errorf("ping: %w", err)
	}

	return &Client{conn: conn}, nil
}

func (c *Client) Close() error {
	return c.conn.Close()
}

func (c *Client) InsertEvents(ctx context.Context, rows []EventRow) error {
	if len(rows) == 0 {
		return nil
	}

	batch, err := c.conn.PrepareBatch(ctx, `INSERT INTO codeflow.events (
		event_id, tenant_id, timestamp, session_id, project_dir, command,
		event_type, input_bytes, output_bytes, input_tokens, output_tokens,
		tokens_saved, filter_name, compression_level, latency_ms,
		content_hash, cache_hit, cli_version, machine_id
	)`)
	if err != nil {
		return fmt.Errorf("prepare batch: %w", err)
	}

	for _, r := range rows {
		cacheHitVal := uint8(0)
		if r.CacheHit {
			cacheHitVal = 1
		}
		if err := batch.Append(
			r.EventID, r.TenantID, r.Timestamp, r.SessionID, r.ProjectDir, r.Command,
			r.EventType, r.InputBytes, r.OutputBytes, r.InputTokens, r.OutputTokens,
			r.TokensSaved, r.FilterName, r.CompressionLevel, r.LatencyMs,
			r.ContentHash, cacheHitVal, r.CLIVersion, r.MachineID,
		); err != nil {
			return fmt.Errorf("append row: %w", err)
		}
	}

	return batch.Send()
}

func (c *Client) GetOverview(ctx context.Context, tenantID string) (*OverviewStats, error) {
	var stats OverviewStats

	row := c.conn.QueryRow(ctx, `
		SELECT
			sum(input_tokens) as total_input,
			sum(output_tokens) as total_output,
			sum(tokens_saved) as total_saved,
			count() as event_count
		FROM codeflow.events
		WHERE tenant_id = $1
	`, tenantID)

	if err := row.Scan(&stats.TotalInputTokens, &stats.TotalOutputTokens, &stats.TotalSaved, &stats.EventCount); err != nil {
		return nil, fmt.Errorf("overview query: %w", err)
	}

	if stats.TotalInputTokens > 0 {
		stats.SavingsPct = float64(stats.TotalSaved) / float64(stats.TotalInputTokens) * 100
	}

	rows, err := c.conn.Query(ctx, `
		SELECT command, sum(tokens_saved) as saved, count() as cnt
		FROM codeflow.events
		WHERE tenant_id = $1
		GROUP BY command
		ORDER BY saved DESC
		LIMIT 10
	`, tenantID)
	if err != nil {
		return nil, fmt.Errorf("top commands query: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var cmd CommandStat
		if err := rows.Scan(&cmd.Command, &cmd.Saved, &cmd.Count); err != nil {
			continue
		}
		stats.TopCommands = append(stats.TopCommands, cmd)
	}

	return &stats, nil
}

