import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import Link from "next/link";
import "./globals.css";

const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

export const metadata: Metadata = {
  title: "CODEFLOW Dashboard",
  description: "AI coding cost intelligence — see your token savings",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="en"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
    >
      <body className="min-h-full flex">
        <Sidebar />
        <main className="flex-1 p-6 bg-background">{children}</main>
      </body>
    </html>
  );
}

function Sidebar() {
  return (
    <aside className="w-56 border-r bg-muted/40 p-4 flex flex-col gap-1">
      <div className="font-bold text-lg mb-4 tracking-tight">CODEFLOW</div>
      <NavLink href="/">Overview</NavLink>
      <NavLink href="/settings">Settings</NavLink>
    </aside>
  );
}

function NavLink({
  href,
  children,
}: {
  href: string;
  children: React.ReactNode;
}) {
  return (
    <Link
      href={href}
      className="block px-3 py-2 rounded-md text-sm hover:bg-accent hover:text-accent-foreground transition-colors"
    >
      {children}
    </Link>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import {
  fetchOverview,
  formatTokens,
  estimateCost,
  type OverviewStats,
} from "@/lib/api";

export default function OverviewPage() {
  const [stats, setStats] = useState<OverviewStats | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchOverview()
      .then(setStats)
      .catch((e) => setError(e.message))
      .finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-muted-foreground">Loading...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-4">
        <h1 className="text-2xl font-bold">Overview</h1>
        <Card>
          <CardContent className="pt-6">
            <p className="text-muted-foreground">
              Could not connect to CODEFLOW API. Make sure the ingest server is
              running.
            </p>
            <p className="text-sm text-muted-foreground mt-2">
              Run:{" "}
              <code className="bg-muted px-1 rounded">
                cd cloud && go run ./cmd/ingest
              </code>
            </p>
          </CardContent>
        </Card>
        <DemoStats />
      </div>
    );
  }

  if (!stats || stats.event_count === 0) {
    return (
      <div className="space-y-4">
        <h1 className="text-2xl font-bold">Overview</h1>
        <Card>
          <CardContent className="pt-6">
            <p className="text-muted-foreground">
              No events yet. Install CODEFLOW hooks and start coding.
            </p>
            <p className="text-sm text-muted-foreground mt-2">
              Run:{" "}
              <code className="bg-muted px-1 rounded">
                codeflow init && codeflow sync --once
              </code>
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return <StatsView stats={stats} />;
}

function StatsView({ stats }: { stats: OverviewStats }) {
  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold">Overview</h1>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <MetricCard
          title="Tokens Saved"
          value={formatTokens(stats.total_saved)}
          description={`${estimateCost(stats.total_saved)} estimated savings`}
        />
        <MetricCard
          title="Savings Rate"
          value={`${stats.savings_pct.toFixed(1)}%`}
          description="of input tokens saved"
        />
        <MetricCard
          title="Events Tracked"
          value={formatTokens(stats.event_count)}
          description="command executions"
        />
        <MetricCard
          title="Input Tokens"
          value={formatTokens(stats.total_input_tokens)}
          description={`${formatTokens(stats.total_output_tokens)} after compression`}
        />
      </div>

      {stats.top_commands && stats.top_commands.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Top Commands by Savings</CardTitle>
            <CardDescription>
              Commands with the highest token savings
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Command</TableHead>
                  <TableHead className="text-right">Tokens Saved</TableHead>
                  <TableHead className="text-right">Executions</TableHead>
                  <TableHead className="text-right">Est. Cost Saved</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {stats.top_commands.map((cmd) => (
                  <TableRow key={cmd.command}>
                    <TableCell>
                      <code className="bg-muted px-1.5 py-0.5 rounded text-sm">
                        {cmd.command}
                      </code>
                    </TableCell>
                    <TableCell className="text-right">
                      <Badge variant="secondary">
                        {formatTokens(cmd.saved)}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">{cmd.count}x</TableCell>
                    <TableCell className="text-right">
                      {estimateCost(cmd.saved)}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

function DemoStats() {
  const demo: OverviewStats = {
    total_input_tokens: 125000,
    total_output_tokens: 62500,
    total_saved: 62500,
    savings_pct: 50.0,
    event_count: 847,
    top_commands: [
      { command: "git diff", saved: 28000, count: 156 },
      { command: "git status", saved: 12400, count: 312 },
      { command: "cargo test", saved: 9800, count: 89 },
      { command: "npm test", saved: 7200, count: 142 },
      { command: "tsc", saved: 5100, count: 148 },
    ],
  };

  return (
    <div className="space-y-4">
      <p className="text-sm text-muted-foreground italic">
        Showing demo data:
      </p>
      <StatsView stats={demo} />
    </div>
  );
}

function MetricCard({
  title,
  value,
  description,
}: {
  title: string;
  value: string;
  description: string;
}) {
  return (
    <Card>
      <CardHeader className="pb-2">
        <CardDescription>{title}</CardDescription>
        <CardTitle className="text-3xl">{value}</CardTitle>
      </CardHeader>
      <CardContent>
        <p className="text-sm text-muted-foreground">{description}</p>
      </CardContent>
    </Card>
  );
}

