package api

import (
	"log/slog"
	"net/http"

	"github.com/codeflow-dev/codeflow/cloud/internal/clickhouse"
)

func NewRouter(ch *clickhouse.Client, logger *slog.Logger) http.Handler {
	mux := http.NewServeMux()

	h := &handler{ch: ch, logger: logger}

	mux.HandleFunc("POST /v1/events", h.handleIngestEvents)
	mux.HandleFunc("GET /v1/overview", h.handleOverview)
	mux.HandleFunc("GET /v1/projects", h.handleListProjects)
	mux.HandleFunc("GET /v1/projects/{id}/stats", h.handleProjectStats)
	mux.HandleFunc("GET /v1/savings/trend", h.handleSavingsTrend)
	mux.HandleFunc("GET /healthz", handleHealthz)

	rl := newRateLimiter()

	var wrapped http.Handler = mux
	wrapped = withRateLimit(rl)(wrapped)
	wrapped = withTenantAuth(wrapped)
	wrapped = withCORS(wrapped)
	wrapped = withLogging(logger, wrapped)

	return wrapped
}

func handleHealthz(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(`{"status":"ok"}`))
}

func withLogging(logger *slog.Logger, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		logger.Info("request",
			"method", r.Method,
			"path", r.URL.Path,
			"remote", r.RemoteAddr,
		)
		next.ServeHTTP(w, r)
	})
}

