"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import {
  fetchProjects,
  formatTokens,
  estimateCost,
  shortProjectName,
  type ProjectSummary,
} from "@/lib/api";

export default function ProjectsPage() {
  const [projects, setProjects] = useState<ProjectSummary[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchProjects()
      .then((p) => setProjects(p || []))
      .catch((e) => setError(e.message))
      .finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-muted-foreground">Loading...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-4">
        <h1 className="text-2xl font-bold">Projects</h1>
        <Card>
          <CardContent className="pt-6">
            <p className="text-muted-foreground">
              Could not load projects. Make sure the API is running.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (projects.length === 0) {
    return (
      <div className="space-y-4">
        <h1 className="text-2xl font-bold">Projects</h1>
        <Card>
          <CardContent className="pt-6">
            <p className="text-muted-foreground">
              No projects yet. Run CODEFLOW in a project directory and sync
              events.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold">Projects</h1>

      <Card>
        <CardHeader>
          <CardTitle>All Projects</CardTitle>
          <CardDescription>
            {projects.length} project{projects.length !== 1 ? "s" : ""} tracked
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Project</TableHead>
                <TableHead className="text-right">Tokens Saved</TableHead>
                <TableHead className="text-right">Savings</TableHead>
                <TableHead className="text-right">Events</TableHead>
                <TableHead className="text-right">Est. Cost Saved</TableHead>
                <TableHead className="text-right">Last Active</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {projects.map((p) => {
                const encoded = encodeURIComponent(
                  p.project_dir.replaceAll("/", "|")
                );
                return (
                  <TableRow key={p.project_dir}>
                    <TableCell>
                      <Link
                        href={`/projects/${encoded}`}
                        className="font-medium hover:underline"
                      >
                        {shortProjectName(p.project_dir)}
                      </Link>
                      <p className="text-xs text-muted-foreground mt-0.5">
                        {p.project_dir}
                      </p>
                    </TableCell>
                    <TableCell className="text-right">
                      <Badge variant="secondary">
                        {formatTokens(p.total_saved)}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      {p.savings_pct.toFixed(1)}%
                    </TableCell>
                    <TableCell className="text-right">
                      {p.event_count.toLocaleString()}
                    </TableCell>
                    <TableCell className="text-right">
                      {estimateCost(p.total_saved)}
                    </TableCell>
                    <TableCell className="text-right text-sm text-muted-foreground">
                      {formatRelativeTime(p.last_event_at)}
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  );
}

function formatRelativeTime(iso: string): string {
  const date = new Date(iso);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffH = Math.floor(diffMs / (1000 * 60 * 60));

  if (diffH < 1) return "just now";
  if (diffH < 24) return `${diffH}h ago`;
  const diffD = Math.floor(diffH / 24);
  if (diffD < 30) return `${diffD}d ago`;
  return date.toLocaleDateString();
}

