        <MetricCard
          title="Savings Rate"
          value={`${summary.savings_pct.toFixed(1)}%`}
          description="of input tokens"
        />
        <MetricCard
          title="Events"
          value={summary.event_count.toLocaleString()}
          description="command executions"
        />
        <MetricCard
          title="Last Active"
          value={new Date(summary.last_event_at).toLocaleDateString()}
          description={new Date(summary.last_event_at).toLocaleTimeString()}
