                  <YAxis
                    tickFormatter={(v: number) => formatTokens(v)}
                    className="text-xs"
                  />
                  <Tooltip
                    formatter={(value: number) => [
                      formatTokens(value),
                      "Saved",
                    ]}
                  />
                  <Bar
                    dataKey="total_saved"
                    fill="hsl(221, 83%, 53%)"
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      )}

      {top_filters && top_filters.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Top Commands</CardTitle>
            <CardDescription>
              Commands with highest token savings in this project
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Command</TableHead>
                  <TableHead className="text-right">Tokens Saved</TableHead>
                  <TableHead className="text-right">Executions</TableHead>
                  <TableHead className="text-right">Est. Cost Saved</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
